var surf=UnityEngine.Object.FindFirstObjectByType<Corrigible.Fx.FxLiveDeskSurface>();var src=surf.source;var fx=surf.interaction;var game=src.Game;var checks=new System.Collections.Generic.List<object>();int failed=0;void Check(string name,bool ok,object detail=null){checks.Add(new{name,ok,detail});if(!ok)failed++;}
var cam=UnityEngine.Camera.main;var prev=cam.targetTexture;var rt=new UnityEngine.RenderTexture(1920,1080,24);cam.targetTexture=rt;
void Refresh(){src.Flush();fx.panels.CompleteAnimations();UnityEngine.Canvas.ForceUpdateCanvases();fx.map.cover.Refresh();foreach(var b in UnityEngine.Object.FindObjectsByType<Corrigible.Fx.FxGraphicBatch>(UnityEngine.FindObjectsSortMode.None))b.Refresh();UnityEngine.Canvas.ForceUpdateCanvases();cam.Render();}
bool Click(UnityEngine.RectTransform rect){Refresh();var point=UnityEngine.RectTransformUtility.WorldToScreenPoint(cam,rect.TransformPoint(rect.rect.center));var e=new UnityEngine.EventSystems.PointerEventData(UnityEngine.EventSystems.EventSystem.current){position=point,button=UnityEngine.EventSystems.PointerEventData.InputButton.Left};var hits=new System.Collections.Generic.List<UnityEngine.EventSystems.RaycastResult>();UnityEngine.EventSystems.EventSystem.current.RaycastAll(e,hits);return hits.Count>0&&UnityEngine.EventSystems.ExecuteEvents.ExecuteHierarchy(hits[0].gameObject,e,UnityEngine.EventSystems.ExecuteEvents.pointerClickHandler)!=null;}
try{
game.NewGame("solucan",731u);src.Flush();Corrigible.Desk.IntroView.Instance.Begin();game.SetSpeed(0);Refresh();bool clicked=Click((UnityEngine.RectTransform)fx.map.Find("weu").Node.transform);Refresh();Check("harita-gerçek-raycast",clicked&&fx.State.SelectedRegion=="weu");
int before=game.Sim.Record.commands.Count;clicked=Click(fx.panels.cardView.ui["action.0"].Rect);Refresh();Check("izleme-gerçek-raycast-komutu",clicked&&game.Sim.Record.commands.Count==before+1&&game.Sim.Record.commands.Last().kind=="act");
fx.Command("closeLarge");fx.ClearSelection();fx.Escape();Refresh();bool previous=fx.clock.Reduced;var reduce=fx.panels.pause.GetComponentsInChildren<Corrigible.Fx.FxDeskCommandTarget>(true).Single(x=>x.command=="reduced");clicked=Click((UnityEngine.RectTransform)reduce.transform);Refresh();Check("azaltılmış-hareket-tıklama",clicked&&fx.clock.Reduced!=previous&&UnityEngine.PlayerPrefs.GetInt(Corrigible.Fx.FxDebugMenu.ReducedKey,-1)==(fx.clock.Reduced?1:0));fx.Command("reduced");
var settings=fx.panels.pause.GetComponentsInChildren<Corrigible.Fx.FxDeskCommandTarget>(true).Single(x=>x.command=="settings");clicked=Click((UnityEngine.RectTransform)settings.transform);Refresh();Check("ayarlar-menü-tıklama",clicked&&Corrigible.Desk.SettingsView.Instance.IsOpen);Corrigible.Desk.SettingsView.Instance.Close();fx.Command("resume");Refresh();
fx.Select("weu");Refresh();var diploma=surf.regionTools[0].diplomacy;before=game.Sim.Record.commands.Count;fx.Command(diploma.command,diploma.argument);Refresh();Check("diplomasi-gerçek-komutu",game.Sim.Record.commands.Count==before+1&&game.Sim.Record.commands.Last().kind=="diplomacy");
}catch(System.Exception e){Check("exception",false,e.ToString());}finally{cam.targetTexture=prev;rt.Release();UnityEngine.Object.DestroyImmediate(rt);}
var result=new{total=checks.Count,failed,checks};System.IO.File.WriteAllText("Docs/UI_Fx/captures/Live/input-qa.json",Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented));return new{total=checks.Count,failed};
